<?php
require_once __DIR__ . '/../config/auth.php';require_student();
$stmt=db()->prepare('SELECT email FROM users WHERE id=?');$stmt->execute([$_SESSION['student_id']]);$email=$stmt->fetchColumn();$docs=db()->prepare('SELECT d.id,d.document_type,d.uploaded_at,a.application_number FROM application_documents d JOIN applications a ON a.id=d.application_id WHERE a.email=? ORDER BY d.uploaded_at DESC');$docs->execute([$email]);$documents=$docs->fetchAll();$accepted=db()->prepare('SELECT id,application_number,created_at FROM applications WHERE email=? AND status="Accepted" ORDER BY created_at DESC');$accepted->execute([$email]);$acceptedApplications=$accepted->fetchAll();$pageTitle='My documents';include __DIR__.'/../includes/header.php';
?><section class="page-hero"><div class="container"><p class="eyebrow">Student portal</p><h1>My documents.</h1></div></section><section class="content-section container"><div class="content-panel"><?php foreach($acceptedApplications as $application):?><article class="result-row"><div><h3>Admission letter</h3><p><?= e($application['application_number']) ?> · Accepted</p></div><a href="<?= e(url('student/admission.php?id='.(int)$application['id'])) ?>" class="text-link">View / print <span>↓</span></a></article><?php endforeach;?><?php foreach($documents as $doc):?><article class="result-row"><div><h3><?= e(ucfirst($doc['document_type'])) ?></h3><p><?= e($doc['application_number']) ?> · <?= e(date('d M Y',strtotime($doc['uploaded_at']))) ?></p></div><a href="<?= e(url('student/document.php?id='.$doc['id'])) ?>" class="text-link">Download <span>↓</span></a></article><?php endforeach;?><?php if(!$documents&&!$acceptedApplications):?><p class="empty-state">No application documents are linked to your account.</p><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>